
clear all, close all,

load('Q1data.mat','x','labels');
x1 = x(:,labels==0);
x2 = x(:,labels==1);

N1 = size(x1,2);
N2 = size(x2,2);

p = [0.35,0.65];

mu1hat = mean(x1,2); S1hat = cov(x1');
mu2hat = mean(x2,2); S2hat = cov(x2');


Sb = (mu1hat-mu2hat)*(mu1hat-mu2hat)';
Sw = S1hat + S2hat;


[V,D] = eig(inv(Sw)*Sb);
[~,ind] = sort(diag(D),'descend');
w = V(:,ind(1));


y1 = w'*x1;
y2 = w'*x2;

if mean(y2)<=mean(y1)
    w = -w;
    y1 = -y1;
    y2 = -y2;
end


% AI-assisted: Keep projected scores aligned with original labels
discriminantScoresLDA = w'*x;

[Pfp,Ptp,Perror,thresholdList] = ...
    ROCcurve(discriminantScoresLDA,labels);

Pfn = 1-Ptp;


PerrorWeighted = p(1)*Pfp + p(2)*Pfn;

[minPerror,indexMin] = min(PerrorWeighted);

tauEmpirical = thresholdList(indexMin);

PfpMin = Pfp(indexMin);
PtpMin = Ptp(indexMin);
PfnMin = Pfn(indexMin);

fprintf('\nQuestion 1 - Part C\n'); %[output:1315bcfa]
fprintf('Empirical optimal tau: %.6f\n',tauEmpirical); %[output:5f89cf60]
fprintf('Minimum P(error): %.6f\n',minPerror); %[output:00a61544]
fprintf('P(False Positive): %.6f\n',PfpMin); %[output:97b44afe]
fprintf('P(True Positive): %.6f\n',PtpMin); %[output:41c173ed]
fprintf('P(False Negative): %.6f\n',PfnMin); %[output:1590fb85]

fprintf('\nFisher LDA projection vector:\n'); %[output:3a33ce77]
disp(w); %[output:4abd9eba]




figure(1), clf, %[output:31fc92ec]
plot(Pfp,Ptp,'og'), %[output:31fc92ec]
hold on, %[output:31fc92ec]
plot(PfpMin,PtpMin,'ro','MarkerSize',12,'LineWidth',2), %[output:31fc92ec]
xlabel('P(False+)'), %[output:31fc92ec]
ylabel('P(True+)'), %[output:31fc92ec]
title('ROC Curve for Fisher LDA Classifier'), %[output:31fc92ec]
legend('ROC Curve','Minimum P(error)','Location','southeast'), %[output:31fc92ec]
grid on, %[output:31fc92ec]

exportgraphics(figure(1),'Q1_C_ROC.png','Resolution',300); %[output:31fc92ec]




A = load('Q1_A2_results.mat');
B = load('Q1_B_results.mat');

PerrorA = p(1)*A.Pfp + p(2)*A.Pfn;
PerrorB = p(1)*B.Pfp + p(2)*B.Pfn;

minPerrorA = min(PerrorA);
minPerrorB = min(PerrorB);

fprintf('\nComparison of Classifiers\n'); %[output:6245a55e]
fprintf('Part A minimum P(error): %.6f\n',minPerrorA); %[output:882f769d]
fprintf('Part B minimum P(error): %.6f\n',minPerrorB); %[output:1a84e68d]
fprintf('Part C minimum P(error): %.6f\n',minPerror); %[output:466fbdc0]

% AI-assisted: Combine all three classifiers in one ROC comparison
figure(2), clf, %[output:9a8e8aea]
plot(A.Pfp,A.Ptp,'b','LineWidth',2), %[output:9a8e8aea]
hold on, %[output:9a8e8aea]
plot(B.Pfp,B.Ptp,'m','LineWidth',2), %[output:9a8e8aea]
plot(Pfp,Ptp,'g','LineWidth',2), %[output:9a8e8aea]
plot(PfpMin,PtpMin,'ro','MarkerSize',10,'LineWidth',2), %[output:9a8e8aea]
xlabel('P(False+)'), %[output:9a8e8aea]
ylabel('P(True+)'), %[output:9a8e8aea]
title('ROC Comparison: ERM, Naive Bayes, and Fisher LDA'), %[output:9a8e8aea]
legend('Part A - True Model','Part B - Naive Bayes', ... %[output:9a8e8aea]
       'Part C - Fisher LDA','LDA Minimum P(error)', ... %[output:9a8e8aea]
       'Location','southeast'), %[output:9a8e8aea]
xlim([0 1]), %[output:9a8e8aea]
ylim([0 1]), %[output:9a8e8aea]
grid on, %[output:9a8e8aea]

exportgraphics(figure(2),'Q1_C_vs_A_B_ROC.png','Resolution',300); %[output:9a8e8aea]

save('Q1_C_results.mat','w','thresholdList', ...
     'Pfp','Ptp','Pfn','tauEmpirical','minPerror');


function [Pfp,Ptp,Perror,thresholdList] = ROCcurve(discriminantScores,labels)

[sortedScores,ind] = sort(discriminantScores,'ascend');

thresholdList = [min(sortedScores)-eps, ...
    (sortedScores(1:end-1)+sortedScores(2:end))/2, ...
    max(sortedScores)+eps];

for i = 1:length(thresholdList)

    tau = thresholdList(i);
    decisions = (discriminantScores >= tau);

    Ptn(i) = length(find(decisions==0 & labels==0)) ...
        /length(find(labels==0));

    Pfp(i) = length(find(decisions==1 & labels==0)) ...
        /length(find(labels==0));

    Ptp(i) = length(find(decisions==1 & labels==1)) ...
        /length(find(labels==1));

    Perror(i) = sum(decisions~=labels)/length(labels);

end

end


